/* Jap_Gra_N5 lesson page — renders from window.LESSON (generated by build.py) */
(function(){
const L = window.LESSON, N = L.id, TOTAL_LESSONS = window.TOTAL_LESSONS || 80;
const $ = s => document.querySelector(s);
const store = {
  get(k){ try{ return JSON.parse(localStorage.getItem(k)); }catch(e){ return null; } },
  set(k,v){ try{ localStorage.setItem(k,JSON.stringify(v)); }catch(e){} }
};
const PROG='jap-gra-n5-progress', PREF='jap-gra-n5-prefs';
const progress = () => store.get(PROG) || {};
const prefs = Object.assign({furi:true, rom:true, slow:false, nokor:false}, store.get(PREF)||{});
const fmt = n => (Math.round(n*10)/10).toString();
const esc = s => String(s).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;');
const state = {}, marks = {};
let lastResult = null, focusedInput = null;
const total = () => L.ex.reduce((n,e)=>n+e.items.length,0);

/* ---------- romaji / kana ---------- */
const R2K = (()=>{
  const m = {};
  const rows = {'':'あいうえお',k:'かきくけこ',g:'がぎぐげご',s:'さしすせそ',z:'ざじずぜぞ',t:'たちつてと',d:'だぢづでど',n:'なにぬねの',h:'はひふへほ',b:'ばびぶべぼ',p:'ぱぴぷぺぽ',m:'まみむめも',r:'らりるれろ'};
  const V='aiueo';
  for(const c in rows) for(let i=0;i<5;i++) m[c+V[i]] = rows[c][i];
  m.ya='や';m.yu='ゆ';m.yo='よ';m.wa='わ';m.wo='を';m.wi='うぃ';m.we='うぇ';
  m.si='し';m.ti='ち';m.tu='つ';m.hu='ふ';m.zi='じ';m.di='ぢ';m.du='づ';
  m.shi='し';m.chi='ち';m.tsu='つ';m.fu='ふ';m.ji='じ';
  const small={a:'ゃ',u:'ゅ',o:'ょ'};
  const yo = {k:'き',g:'ぎ',n:'に',h:'ひ',b:'び',p:'ぴ',m:'み',r:'り'};
  for(const c in yo) for(const v in small) m[c+'y'+v] = yo[c]+small[v];
  for(const v in small){
    m['sh'+v]='し'+small[v]; m['ch'+v]='ち'+small[v]; m['j'+v]='じ'+small[v];
    m['sy'+v]='し'+small[v]; m['ty'+v]='ち'+small[v]; m['zy'+v]='じ'+small[v]; m['jy'+v]='じ'+small[v]; m['dy'+v]='ぢ'+small[v]; m['cy'+v]='ち'+small[v];
  }
  m.she='しぇ';m.che='ちぇ';m.je='じぇ';m.fa='ふぁ';m.fi='ふぃ';m.fe='ふぇ';m.fo='ふぉ';m.tsa='つぁ';m.tsi='つぃ';m.tse='つぇ';m.tso='つぉ';
  m.thi='てぃ';m.dhi='でぃ';m.va='ゔぁ';m.vi='ゔぃ';m.vu='ゔ';m.ve='ゔぇ';m.vo='ゔぉ';
  m.la='ぁ';m.li='ぃ';m.lu='ぅ';m.le='ぇ';m.lo='ぉ';m.xa='ぁ';m.xi='ぃ';m.xu='ぅ';m.xe='ぇ';m.xo='ぉ';
  m.lya='ゃ';m.lyu='ゅ';m.lyo='ょ';m.xya='ゃ';m.xyu='ゅ';m.xyo='ょ';m.ltu='っ';m.xtu='っ';m.ltsu='っ';
  return m;
})();
function r2k(src){
  let s = src.toLowerCase().replace(/ā/g,'aa').replace(/ī/g,'ii').replace(/ū/g,'uu').replace(/ē/g,'ee').replace(/ō/g,'ou');
  let out='', i=0;
  while(i<s.length){
    const c=s[i];
    if(!/[a-z\-']/.test(c)){ out+=c; i++; continue; }
    if(c==='-'){ out+='ー'; i++; continue; }
    if(c==="'"){ i++; continue; }
    // double consonant
    if(i+1<s.length && c===s[i+1] && /[bcdfghjklmpqrstvwxyz]/.test(c) ){ out+='っ'; i++; continue; }
    if(c==='t' && s.startsWith('tch',i)){ out+='っ'; i++; continue; }
    if(c==='n'){
      const nx=s[i+1], n2=s[i+2];
      if(nx==="'"){ out+='ん'; i+=2; continue; }
      if(nx==='n'){ out+='ん'; i+= (n2 && /[aiueoy]/.test(n2)) ? 1 : 2; continue; }
      if(nx===undefined || !/[aiueoy]/.test(nx)){ out+='ん'; i++; continue; }
    }
    let hit=null;
    for(const len of [4,3,2,1]){ const k=s.substr(i,len); if(R2K[k]){ hit=[k,R2K[k]]; break; } }
    if(hit){ out+=hit[1]; i+=hit[0].length; } else { out+=c; i++; }
  }
  return out;
}
const kata2hira = s => s.replace(/[ァ-ヶ]/g, c=>String.fromCharCode(c.charCodeAt(0)-0x60));
const ROWS = {A:'あかさたなはまやらわがざだばぱぁゃゎ', I:'いきしちにひみりぎじぢびぴぃ', U:'うくすつぬふむゆるぐずづぶぷぅゅゔ', E:'えけせてねへめれげぜでべぺぇ', O:'おこそとのほもよろをごぞどぼぽぉょ'};
const rowOf = ch => { for(const r in ROWS) if(ROWS[r].includes(ch)) return r; return ''; };
function canon(raw){
  let s = kata2hira(r2k(String(raw))).replace(/[\s。、，．,.!?！？・…「」『』（）()~〜\-—―"'“”:;：；]/g,'');
  let out='', prev='';
  for(const ch of s){
    let o=ch, r=rowOf(ch);
    if(ch==='ー'){ o = {A:'あ',I:'い',U:'う',E:'い',O:'う'}[prev] || ''; r=prev; }
    else {
      if(ch==='を'){ o='お'; r='O'; }
      if(o==='お' && prev==='O') o='う';
      else if(o==='え' && prev==='E') o='い';
    }
    out+=o; prev=r;
  }
  return out;
}
function lenient(c){
  let out='', prev='';
  for(const ch of c){
    const r=rowOf(ch);
    if((ch==='あ'&&prev==='A')||(ch==='い'&&(prev==='I'||prev==='E'))||(ch==='う'&&(prev==='U'||prev==='O'))) { continue; }
    out+=ch; prev=r;
  }
  return out;
}
window.__t = {r2k, canon, lenient};

/* ---------- speech ---------- */
let jaVoice=null;
function pickVoice(){
  try{
    const vs=(speechSynthesis.getVoices()||[]).filter(v=>/^ja([-_]|$)/i.test(v.lang));
    jaVoice = vs.find(v=>v.localService) || vs[0] || null;
  }catch(e){}
}
try{ pickVoice(); speechSynthesis.addEventListener('voiceschanged', pickVoice); }catch(e){}
let _u=null, _t=null;
function speak(t){
  if(!t) return;
  try{
    const synth=window.speechSynthesis;
    clearTimeout(_t);
    synth.cancel(); synth.resume(); pickVoice();
    // cancel() immediately followed by speak() is dropped by some browsers: wait a tick
    _t=setTimeout(()=>{
      const u=new SpeechSynthesisUtterance(t); _u=u;   // keep a reference so it is not garbage-collected mid-speech
      u.lang='ja-JP'; if(jaVoice){ u.voice=jaVoice; u.lang=jaVoice.lang; } u.rate = prefs.slow?0.6:0.9;
      synth.speak(u);
    },90);
    const nv=$('#novoice'); if(nv && !jaVoice && !(synth.getVoices()||[]).length) nv.hidden=false;
  }catch(e){}
}
document.addEventListener('click',e=>{
  const s=e.target.closest('[data-say]'); if(s) speak(s.dataset.say);
});
document.addEventListener('keydown',e=>{
  if((e.key==='Enter'||e.key===' ') && e.target.classList && (e.target.classList.contains('ja')||e.target.classList.contains('jt'))){ e.preventDefault(); speak(e.target.dataset.say); }
});

/* ---------- prefs ---------- */
function applyPrefs(){
  document.body.classList.toggle('nofuri', !prefs.furi);
  document.body.classList.toggle('norom', !prefs.rom);
  document.body.classList.toggle('nokor', !!prefs.nokor);
  document.querySelectorAll('[data-pref]').forEach(b=>b.setAttribute('aria-pressed', prefs[b.dataset.pref]?'true':'false'));
}

/* ---------- page ---------- */
function exHTML(e,ei){
  return `<section class="ex" id="ex${ei}">
    <div class="ex-head"><h2>${e.title}</h2><span class="ex-score" id="sc${ei}"></span></div>
    <p class="instr">${e.instr}</p>
    <ol class="items">${e.items.map((it,ii)=>{
      const k=`${ei}-${ii}`;
      let body;
      if(it.t==='text'){
        body = `${it.q}<div class="tin"><input type="text" id="in-${k}" data-k="${k}" autocomplete="off" autocapitalize="none" autocorrect="off" spellcheck="false" lang="ja" aria-label="${ii+1}번 답" placeholder="ひらがな / romaji"><span class="kprev" id="kp-${k}" aria-hidden="true"></span></div>`;
      } else {
        const q = it.bl ? it.q.replace('___',`<span class="blank" id="bl-${k}"></span>`) : it.q;
        body = `${q}<div class="opts" role="radiogroup" aria-label="${ii+1}번 선택지">${it.o.map((o,oi)=>`<button type="button" role="radio" aria-checked="false" data-k="${k}" data-v="${esc(o)}">${it.oh?it.oh[oi]:esc(o)}</button>`).join('')}</div>`;
      }
      return `<li class="item" id="i-${k}"><span class="n">${ii+1}</span><div class="q">${body}</div><div class="fb" id="fb-${k}"></div></li>`;
    }).join('')}</ol></section>`;
}
function build(){
  const T=total(), prev=N>1?N-1:0, next=N<TOTAL_LESSONS?N+1:0;
  $('#app').innerHTML = `
  <div class="studybar"><div class="wrap">
    <div class="sb-row">
      <a class="home" href="../">← 전체 목록</a><span class="unit-tag">LESSON ${N}</span>
      <span class="sb-spacer"></span>
      <span class="count" id="count">답한 문제 0 / ${T}</span>
      <button class="btn" id="gradeBtn">채점하기</button>
    </div>
    <div class="keys">
      <span>표시</span>
      <button type="button" class="tg" data-pref="furi" aria-pressed="true">후리가나</button>
      <button type="button" class="tg" data-pref="rom" aria-pressed="true">로마자</button>
      <button type="button" class="tg" data-pref="nokor" aria-pressed="false">한국어 뜻 가리기</button>
      <button type="button" class="tg" data-pref="slow" aria-pressed="false">느리게 듣기</button>
      <span class="sep"></span>
      <span>입력 도우미</span>${['ー','っ','ん','、','。','？','！'].map(k=>`<button type="button" class="kb" data-k="${k}">${k}</button>`).join('')}
    </div>
    <div class="novoice" id="novoice" hidden>이 기기에는 일본어 음성이 없어서 소리가 나지 않을 수 있어요. 휴대폰이나 크롬·사파리·엣지 브라우저에서 시도해 보세요.</div>
  </div></div>
  <header class="col ch-head"><div class="no">LESSON ${N} · ${L.part}</div><h1><span class="jp">${L.ja}</span><small>${L.ko}</small><small class="en">${L.en}</small></h1></header>
  <main class="col">
    <section class="theory">${L.theory}</section>
    ${L.ex.map(exHTML).join('')}
    <section class="result" id="result" hidden aria-live="polite"></section>
    <div class="pager">${prev?`<a href="../Lesson${prev}/">← ${prev}과 ${L.prevTitle}</a>`:'<span></span>'}${next?`<a href="../Lesson${next}/">${next}과 ${L.nextTitle} →</a>`:'<a href="../">목록으로 →</a>'}</div>
  </main>`;
  applyPrefs();
  $('#gradeBtn').addEventListener('click',grade);
  document.querySelectorAll('[data-pref]').forEach(b=>b.addEventListener('click',()=>{ prefs[b.dataset.pref]=!prefs[b.dataset.pref]; store.set(PREF,prefs); applyPrefs(); }));
  const keys=document.querySelector('.keys');
  keys.addEventListener('mousedown',e=>{ if(e.target.classList.contains('kb')) e.preventDefault(); });
  keys.addEventListener('click',e=>{
    if(!e.target.classList.contains('kb')) return;
    const k=e.target.dataset.k;
    const inp = focusedInput && document.body.contains(focusedInput) ? focusedInput : null;
    if(!inp) return;
    const s=inp.selectionStart??inp.value.length, en=inp.selectionEnd??s;
    inp.value=inp.value.slice(0,s)+k+inp.value.slice(en); inp.setSelectionRange(s+k.length,s+k.length); inp.focus();
    inp.dispatchEvent(new Event('input',{bubbles:true}));
  });
  updateCount();
}
function setPick(li,v,btnHtml){
  const bl=li.querySelector('.blank'); if(bl) bl.innerHTML=btnHtml;
  li.querySelectorAll('.opts button').forEach(b=>b.setAttribute('aria-checked',b.dataset.v===v?'true':'false'));
}
function clearMark(k){
  delete marks[k]; const li=document.getElementById('i-'+k); if(!li) return;
  li.classList.remove('ok','bad','half'); document.getElementById('fb-'+k).innerHTML='';
}
function updateCount(){
  let a=0; L.ex.forEach((e,ei)=>e.items.forEach((it,ii)=>{ const v=state[`${ei}-${ii}`]; if(v!==undefined&&v!=='') a++; }));
  const el=$('#count'); if(el) el.textContent=`답한 문제 ${a} / ${total()}`; return a;
}
document.addEventListener('focusin',e=>{ if(e.target.matches && e.target.matches('.q input')) focusedInput=e.target; });
document.addEventListener('input',e=>{
  const t=e.target; if(!t.matches||!t.matches('.q input')) return;
  const k=t.dataset.k; state[k]=t.value; clearMark(k); updateCount();
  const kp=document.getElementById('kp-'+k);
  if(kp){ const v=t.value; kp.textContent = /[a-zA-Zāīūēō]/.test(v) ? '→ '+r2k(v).replace(/[a-z]/g,'') : ''; }
});
document.addEventListener('click',e=>{
  const b=e.target.closest('.opts button'); if(!b) return;
  const k=b.dataset.k;
  state[k]=b.dataset.v; setPick(document.getElementById('i-'+k),b.dataset.v,b.innerHTML); clearMark(k); updateCount();
});
document.addEventListener('keydown',e=>{
  if(e.key==='Enter' && e.target.matches && e.target.matches('.q input')){
    const ins=[...document.querySelectorAll('.q input')]; const i=ins.indexOf(e.target); if(ins[i+1]) ins[i+1].focus();
  }
});

/* ---------- grading ---------- */
function judge(it,v){
  if(v===undefined||v==='') return 'none';
  if(it.t==='pick') return v===it.a?'ok':'bad';
  const c=canon(v); if(!c) return 'none';
  const cs=it.a.map(canon);
  if(cs.includes(c)) return 'ok';
  const lc=lenient(c);
  if(cs.some(a=>lenient(a)===lc)) return 'half';
  return 'bad';
}
function showMark(ei,ii){
  const k=`${ei}-${ii}`, it=L.ex[ei].items[ii], m=marks[k], li=document.getElementById('i-'+k), fb=document.getElementById('fb-'+k);
  li.classList.remove('ok','bad','half'); if(!m) return; li.classList.add(m);
  const ans = it.ah || esc(it.t==='pick'?it.a:it.a[0]);
  const why = it.why||L.ex[ei].rule;
  const head = m==='ok'?'✔ 정답':m==='half'?`△ 장음(ー·おう·おお 등)을 확인하세요 · 정답 <span class="ans">${ans}</span> (0.5점)`:`✘ 오답 · 정답 <span class="ans">${ans}</span>`;
  fb.innerHTML = head + (why?`<span class="why"><b>해설</b> ${why}</span>`:'');
}
function grade(){
  const res={ex:[],score:0,total:0,blank:0};
  L.ex.forEach((e,ei)=>{
    let s=0;
    e.items.forEach((it,ii)=>{
      const k=`${ei}-${ii}`, j=judge(it,state[k]);
      if(j==='none'){ marks[k]='bad'; res.blank++; } else marks[k]=j;
      if(j==='ok') s+=1; else if(j==='half') s+=.5;
      showMark(ei,ii);
      if(j==='none'){ document.getElementById('fb-'+k).innerHTML='✘ 미응답 · 정답 <span class="ans">'+(it.ah||esc(it.t==='pick'?it.a:it.a[0]))+'</span>'+`<span class="why"><b>해설</b> ${it.why||e.rule}</span>`; }
    });
    document.getElementById('sc'+ei).textContent=`${fmt(s)} / ${e.items.length}`;
    res.ex.push({title:e.short,s,t:e.items.length}); res.score+=s; res.total+=e.items.length;
  });
  lastResult=res;
  const pr=progress(), old=pr['ch'+N];
  if(!old||res.score>=old.score){ pr['ch'+N]={score:res.score,total:res.total}; store.set(PROG,pr); }
  renderResult(true);
}
function renderResult(scroll){
  const res=lastResult, pct=Math.round(res.score/res.total*100), name=(store.get('gdu-name')||'').trim();
  const msg = pct>=90?['훌륭해요!','거의 완벽합니다. 다음 과로 넘어가도 좋아요.']:pct>=70?['잘했어요!','틀린 문제의 해설을 읽고 다시 도전해 보세요.']:pct>=50?['조금만 더!','표현을 소리 내어 한 번 더 읽고 틀린 문제를 다시 풀어 보세요.']:['다시 도전해요','예문을 눌러 소리를 들으며 천천히 따라 읽은 뒤 다시 풀어 보세요.'];
  const R=54, C=2*Math.PI*R;
  const el=$('#result'); el.hidden=false;
  el.innerHTML=`
   <div class="r-top">
    <div class="ring"><svg viewBox="0 0 132 132" aria-hidden="true"><circle class="bg" cx="66" cy="66" r="${R}"/><circle class="fg" cx="66" cy="66" r="${R}" stroke-dasharray="${C*pct/100} ${C}"/></svg><b>${pct}%</b></div>
    <div class="r-txt"><div class="eyebrow">${name?esc(name)+' · ':''}LESSON ${N} 결과</div><h2>${fmt(res.score)} / ${res.total}점 · ${msg[0]}</h2><p>${msg[1]}</p>${res.blank?`<p>풀지 않은 문제가 ${res.blank}개 있어요. 오답으로 처리되었습니다.</p>`:''}</div>
   </div>
   <div class="brk">${res.ex.map(e=>`<div><span>${e.title}</span><span class="bar"><i style="width:${e.s/e.t*100}%"></i></span><span>${fmt(e.s)}/${e.t}</span></div>`).join('')}</div>
   <div class="r-act"><button class="btn" id="retryWrong">틀린 문제만 다시 풀기</button><button class="btn ghost" id="retryAll">처음부터 다시 풀기</button>${N<TOTAL_LESSONS?`<a class="btn ghost" href="../Lesson${N+1}/">다음 과로 →</a>`:''}</div>`;
  $('#retryWrong').onclick=()=>retry(false); $('#retryAll').onclick=()=>retry(true);
  if(scroll) el.scrollIntoView({behavior:'smooth',block:'center'});
}
function retry(all){
  L.ex.forEach((e,ei)=>e.items.forEach((it,ii)=>{
    const k=`${ei}-${ii}`, m=marks[k];
    if(all || m!=='ok'){
      delete state[k]; clearMark(k); const li=document.getElementById('i-'+k);
      if(it.t==='text'){ li.querySelector('input').value=''; const kp=document.getElementById('kp-'+k); if(kp) kp.textContent=''; }
      else { const bl=li.querySelector('.blank'); if(bl) bl.textContent=''; li.querySelectorAll('.opts button').forEach(b=>b.setAttribute('aria-checked','false')); }
    }
  }));
  L.ex.forEach((e,ei)=>{ $('#sc'+ei).textContent=''; });
  lastResult=null; $('#result').hidden=true; updateCount();
  const first=document.querySelector('li.item:not(.ok)'); if(first) first.scrollIntoView({behavior:'smooth',block:'center'}); else window.scrollTo({top:0,behavior:'smooth'});
}
build();
})();
